/*
 * Illustrations drawn in code. Large line art lives as static files in
 * public/art (generated by referensi/tools/make-art.mjs); the pieces here
 * carry text or data and so are rendered inline.
 */

const ROWS: { label: string; value: string; barred: boolean }[] = [
  { label: "Counterparty", value: "0x8b41…c07e", barred: true },
  { label: "Delivers", value: "250,000.00 USDG", barred: true },
  { label: "Receives", value: "1,190 NVDA token", barred: true },
  { label: "Memo", value: "Q4 rebalance, desk 3", barred: true },
  { label: "Commitment", value: "0x5d2e…91af", barred: false },
  { label: "Status", value: "Settled · final", barred: false },
];

/** A settlement statement whose private lines bar and unbar: one record, seen by a party and by the public. */
export function StatementArt() {
  return (
    <figure className="relative min-w-0 overflow-hidden rounded-[16px] bg-black p-[30px] text-white max-md:p-5">
      <div className="flex items-center justify-between gap-3 border-b border-white/15 pb-3">
        <span className="text-[13px] font-semibold tracking-[0.04em] text-white/70 uppercase">Settlement statement</span>
        <span className="rounded-full border border-white/30 px-2.5 py-0.5 text-[12px] text-white/80">Example</span>
      </div>
      <dl className="mt-1">
        {ROWS.map((row) => (
          <div key={row.label} className="grid grid-cols-[110px_minmax(0,1fr)] items-center gap-3 border-b border-white/10 py-[10px] last:border-b-0 sm:grid-cols-[140px_minmax(0,1fr)]">
            <dt className="text-[12px] font-semibold tracking-[0.04em] text-white/55 uppercase">{row.label}</dt>
            <dd className="relative min-w-0 truncate font-mono text-[14px] text-white">
              {row.value}
              {row.barred ? <span aria-hidden="true" className="bar-anim absolute inset-y-[3px] left-0 w-[92%] rounded-[3px] bg-accent" /> : null}
            </dd>
          </div>
        ))}
      </dl>
      <p className="mt-4 text-[13px] text-white/70">The public sees the bars. The two parties see the terms.</p>
      <figcaption className="sr-only">
        An example settlement statement. Counterparty, amounts and memo are hidden from the public; the commitment hash and the final status are visible to everyone.
      </figcaption>
    </figure>
  );
}

/** Dot field with a lit cluster of labelled nodes, used in the tab showcase panels. */
export function NodeArt({ labels, seed = 0 }: { labels: [string, string, string, string?]; seed?: number }) {
  const cols = 11,
    rows = 6;
  const dots: { x: number; y: number; ring: boolean }[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const ring = (r * 7 + c * 3 + seed) % 5 === 0;
      dots.push({ x: 40 + c * 62, y: 30 + r * 44, ring });
    }
  }
  const cx = 360 + (seed % 3) * 40 - 40,
    cy = 132;
  const [a, b, c, d] = labels;
  return (
    <svg viewBox="0 0 700 270" className="h-full w-full" role="img" aria-label={`${a} with ${b} and ${c}`} preserveAspectRatio="xMidYMid slice">
      {dots.map((p, i) =>
        p.ring ? <circle key={i} cx={p.x} cy={p.y} r="15" fill="#333" /> : <circle key={i} cx={p.x} cy={p.y} r="1.6" fill="#777" />,
      )}
      <g fontFamily="var(--font-sans)" fontSize="11" fontWeight="600" textAnchor="middle">
        <circle cx={cx} cy={cy} r="44" fill="#875cff" stroke="#c9b6ff" strokeWidth="2" />
        <text x={cx} y={cy - 3} fill="#fff">
          {a}
        </text>
        <text x={cx} y={cy + 12} fill="#fff" fontWeight="400" fontSize="10">
          private record
        </text>
        <circle cx={cx - 92} cy={cy} r="30" fill="#5b3fc2" stroke="#c9b6ff" strokeWidth="1.5" />
        <text x={cx - 92} y={cy + 4} fill="#fff" fontSize="10">
          {b}
        </text>
        <circle cx={cx + 92} cy={cy} r="30" fill="#5b3fc2" stroke="#c9b6ff" strokeWidth="1.5" />
        <text x={cx + 92} y={cy + 4} fill="#fff" fontSize="10">
          {c}
        </text>
        <path d={`M${cx - 62} ${cy}H${cx - 44}M${cx + 44} ${cy}H${cx + 62}`} stroke="#c9b6ff" strokeWidth="2" />
        {d ? (
          <>
            <circle cx={cx} cy={cy - 84} r="24" fill="#a3ffd1" />
            <text x={cx} y={cy - 80} fill="#000" fontSize="10">
              {d}
            </text>
            <path d={`M${cx} ${cy - 60}V${cy - 44}`} stroke="#a3ffd1" strokeWidth="2" />
          </>
        ) : null}
      </g>
    </svg>
  );
}

/** Code panel in the style of a terminal window. */
export function Terminal({ title = "commitment", lines }: { title?: string; lines: { t: string; tone?: "cmd" | "dim" | "ok" }[] }) {
  return (
    <figure className="min-w-0 overflow-hidden rounded-[16px] bg-[#0f0f0f] text-white">
      <div className="flex items-center gap-2 border-b border-white/10 px-4 py-3">
        <span className="size-3 rounded-full bg-[#ff5f57]" />
        <span className="size-3 rounded-full bg-[#febc2e]" />
        <span className="size-3 rounded-full bg-[#28c840]" />
        <span className="ml-3 text-[12px] text-white/45">{title}</span>
      </div>
      <pre className="overflow-x-auto px-5 py-5 font-mono text-[13.5px] leading-[1.75]">
        <code>
          {lines.map((l, i) => (
            <span key={i} className={`block ${l.tone === "dim" ? "text-white/45" : l.tone === "ok" ? "text-accent" : "text-white"}`}>
              {l.tone === "cmd" ? <span className="text-white/45">$ </span> : null}
              {l.t || " "}
            </span>
          ))}
        </code>
      </pre>
    </figure>
  );
}

/**
 * The two-layer picture: who acts, what stays private, what the chain records.
 * Built in HTML so labels wrap and stay readable on a phone.
 */
export function LayerStack() {
  const lane = "grid grid-cols-[34px_minmax(0,1fr)] gap-3 sm:grid-cols-[44px_minmax(0,1fr)]";
  const tag = "flex items-center justify-center rounded-[10px] text-[11px] font-semibold tracking-[0.06em] uppercase [writing-mode:vertical-rl] rotate-180 sm:text-[12px]";
  return (
    <figure className="min-w-0">
      <div className="space-y-4">
        <div className={lane}>
          <span className={`${tag} bg-[#d9cfff] text-black`}>Parties</span>
          <div className="grid grid-cols-2 gap-3 rounded-[16px] bg-paper-2 p-4 sm:grid-cols-4">
            {[
              ["Maker desk", "signs the proposal"],
              ["Counterparty", "signs acceptance"],
              ["Auditor", "holds one view key"],
              ["Public", "reads the tape"],
            ].map(([n, d]) => (
              <div key={n} className="min-w-0 text-center">
                <span className="mx-auto grid size-14 place-items-center rounded-full bg-violet text-white shadow-[0_0_0_6px_#e9e2ff]">
                  <span className="size-2.5 rounded-full bg-white" />
                </span>
                <p className="mt-3 text-[14px] font-semibold text-black">{n}</p>
                <p className="text-[12.5px] text-ink-3">{d}</p>
              </div>
            ))}
          </div>
        </div>
        <div className={lane}>
          <span className={`${tag} bg-[#cfc7bd] text-black`}>Private records</span>
          <div className="grid grid-cols-1 gap-3 rounded-[16px] border border-line p-4 sm:grid-cols-3">
            {[
              ["Settlement terms", "both wallets, both legs, memo"],
              ["Salt", "16 random bytes, never published"],
              ["View key", "opens this one record only"],
            ].map(([n, d]) => (
              <div key={n} className="min-w-0 rounded-[12px] bg-[#efe9ff] px-4 py-3">
                <p className="text-[14px] font-semibold text-black">{n}</p>
                <p className="text-[13px] text-ink-3">{d}</p>
              </div>
            ))}
          </div>
        </div>
        <div className={lane}>
          <span className={`${tag} bg-accent text-black`}>Robinhood Chain</span>
          <div className="night rounded-[16px] bg-board p-4">
            <div className="rounded-full bg-accent px-4 py-2 text-center text-[13px] font-semibold text-black">
              Public tape: commitment hash · status · block
            </div>
            <div className="mt-4 flex items-center justify-between gap-2 overflow-hidden">
              {Array.from({ length: 7 }).map((_, i) => (
                <span
                  key={i}
                  className={`grid size-11 shrink-0 place-items-center rounded-full border ${i === 3 ? "border-accent bg-accent text-black" : "border-white/30 text-white/60"} text-[10px] font-semibold max-sm:size-8`}
                >
                  {i === 3 ? "final" : "blk"}
                </span>
              ))}
            </div>
          </div>
        </div>
      </div>
      <figcaption className="mt-3 text-[13px] text-ink-3">
        Parties sign; the private record stays with them; Robinhood Chain blocks time-stamp only the commitment and its status.
      </figcaption>
    </figure>
  );
}
